export function getMoveById(id){ return COMBAT_MOVES.find(m=>m.id===id); }
export function getMoveByName(name){ return COMBAT_MOVES.find(m=>m.name.toLowerCase()===name.toLowerCase() || m.slug===name.toLowerCase()); }
export function getMovesByCategory(cat){ return COMBAT_MOVES.filter(m=>m.category===cat); }
export function getMovesByIntensity(intensity){ return COMBAT_MOVES.filter(m=>m.intensity===intensity); }
export function getRandomMove(){ return COMBAT_MOVES[Math.floor(Math.random()*COMBAT_MOVES.length)]; }

// Pose generator for each move - returns stickman pose given phase and progress
export function getPoseForMove(move, phase, progress, facing, seed={}) {
  const base = { waistLean:0, chestLean:0, headTilt:0, armL:{upper:0,lower:0}, armR:{upper:0,lower:0}, legL:{upper:0,lower:0}, legR:{upper:0,lower:0}, crouch:0, stance:1, hop:0 };
  const f = facing>=0?1:-1;
  const angles = move.poseAngles;
  let u=0,l=0;
  if (phase==='anticipation') { u = angles.windup[0]*0.3; l = angles.windup[1]*0.3; base.crouch=0.08; base.waistLean=-3*f; }
  else if (phase==='windup') { u = angles.windup[0] + (angles.windup[0]*0.2*progress); l = angles.windup[1]; base.crouch=0.12+progress*0.08; base.waistLean=-8*f*progress; base.chestLean=-4*f*progress; }
  else if (phase==='strike') { const t=progress; u = angles.windup[0] + (angles.strike[0]-angles.windup[0])*t; l = angles.windup[1] + (angles.strike[1]-angles.windup[1])*t; base.waistLean=( -8 + 18*t)*f; base.chestLean=( -4 + 10*t)*f; if(move.category==='kick'||move.category==='knee'){ base.legL.upper = move.leg==='lead'? -20+angles.strike[0]*t*0.5 : 5; base.legR.upper = move.leg==='rear'? -25+angles.strike[0]*t*0.6 : -5; } }
  else if (phase==='impact') { u = angles.strike[0]; l = angles.strike[1]; base.waistLean=11*f; base.chestLean=6*f; base.stance=1.15; if(move.isHead){ base.headTilt=18*f; } }
  else if (phase==='recovery') { u = angles.strike[0] + (10-angles.strike[0])*progress; l = angles.strike[1] + (10-angles.strike[1])*progress; base.waistLean=11*f*(1-progress); base.chestLean=6*f*(1-progress); base.crouch=0.1*(1-progress); }

  if (move.arm==='lead') { if(f>=0){ base.armR.upper=u; base.armR.lower=l; } else { base.armL.upper=u; base.armL.lower=l; } }
  else if (move.arm==='rear') { if(f>=0){ base.armL.upper=u; base.armL.lower=l; } else { base.armR.upper=u; base.armR.lower=l; } }
  else if (move.arm==='both') { base.armL.upper=u*0.9; base.armL.lower=l; base.armR.upper=u; base.armR.lower=l; }
  else if (move.arm==='none' && move.isHead) { base.headTilt = (phase==='strike'?25:10)*f; base.chestLean=8*f; }

  if (move.category==='kick') {
    const legUpper = phase==='strike'? angles.strike[0] : phase==='impact'? angles.strike[0] : 0;
    if (move.leg==='lead') { if(f>=0){ base.legR.upper=legUpper; base.legR.lower=10; } else { base.legL.upper=legUpper; base.legL.lower=10; } }
    else if (move.leg==='rear') { if(f>=0){ base.legL.upper=legUpper; base.legL.lower=15; } else { base.legR.upper=legUpper; base.legR.lower=15; } }
  }

  return base;
}

// Combo linking - smooth flow
export function canLinkMoves(fromMove, toMove, currentProgress) {
  if (currentProgress < fromMove.comboWindow[0] || currentProgress > fromMove.comboWindow[1]) return false;
  if (fromMove.id === toMove.id && !fromMove.isCombo) return false; // no self repeat unless combo move
  return true;
}

// Intensity variants - Light/Medium/Heavy same move with different timing/power
export function getIntensityVariant(move, intensity) {
  const mult = intensity==='Light'?0.8 : intensity==='Heavy'?1.3 : 1.0;
  return {
    ...move,
    intensity,
    damageMult: move.damageMult * mult,
    knockbackMult: move.knockbackMult * mult,
    hitstop: Math.round(move.hitstop * (intensity==='Light'?0.7:intensity==='Heavy'?1.4:1)),
    timing: { ...move.timing, windup: move.timing.windup * (intensity==='Light'?0.7:1.2), recovery: move.timing.recovery * (intensity==='Light'?0.8:1.1) }
  };
}

// Full pack with Light/Medium/Heavy versions = 360 total variants
export const COMBAT_MOVES_WITH_VARIANTS = COMBAT_MOVES.flatMap(m => [
  getIntensityVariant(m, 'Light'),
  getIntensityVariant(m, 'Medium'),
  getIntensityVariant(m, 'Heavy'),
]);

// Hitbox definitions collision-ready
export function getHitboxForMove(move, facing, worldX, worldY) {
  const reach = move.category==='punch'? 52 : move.category==='elbow'? 42 : move.category==='head'? 32 : move.category==='kick'? 72 : move.category==='knee'? 48 : 56;
  const dir = facing>=0?1:-1;
  return {
    x: worldX + dir * reach,
    y: worldY - (move.category==='kick' && move.name.includes('Low') ? 20 : move.category==='head'? 95 : move.category==='knee'? 45 : 65),
    radius: move.hitbox.radius,
    bone: move.hitbox.bone,
    damage: move.damageMult,
    knockback: move.knockbackMult,
    isActive: true,
  };
}

// Squash & Stretch on impact
export function getSquashStretch(move) {
  return { x: move.squashStretch?.x || 1.25, y: move.squashStretch?.y || 0.8, duration: move.squashStretch?.duration || move.hitstop };
}
